    });

    // 4️⃣ Add a layer that draws the buildings
    map.addLayer({
      id: 'nyc-buildings-fill',
      type: 'fill',
      source: 'nyc-buildings',
      'source-layer': 'building',   // <-- check the archive's layer name
      paint: {
        'fill-color': '#ff6600',
        'fill-opacity': 0.6
      }
    });
